CREATE TABLE evento_ordem_retirada(id uuid PRIMARY KEY,organizacao_id uuid NOT NULL,unidade_id uuid NOT NULL,autor_id uuid NOT NULL,comando_id uuid NOT NULL,motivo text NOT NULL CHECK(length(motivo) BETWEEN 1 AND 160),criada_em timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(organizacao_id,id),UNIQUE(organizacao_id,unidade_id,id),FOREIGN KEY(organizacao_id,unidade_id) REFERENCES unidade_hospitalar(organizacao_id,id),FOREIGN KEY(organizacao_id,autor_id) REFERENCES usuario(organizacao_id,id),FOREIGN KEY(organizacao_id,comando_id) REFERENCES comando(organizacao_id,id),ordem_id uuid NOT NULL,versao integer NOT NULL CHECK(versao>0),estado text NOT NULL CHECK(estado IN ('RASCUNHO','AGUARDANDO_RETIRADA','EM_SEPARACAO','CANCELADA')),evento_acesso_id uuid,CHECK((estado='EM_SEPARACAO')=(evento_acesso_id IS NOT NULL)),UNIQUE(organizacao_id,ordem_id,versao),FOREIGN KEY(organizacao_id,unidade_id,ordem_id) REFERENCES ordem_retirada(organizacao_id,unidade_id,id),FOREIGN KEY(organizacao_id,unidade_id,evento_acesso_id) REFERENCES evento_acesso(organizacao_id,unidade_id,id));
