CREATE INDEX ordem_retirada_unidade ON ordem_retirada(organizacao_id,unidade_id,id);
CREATE INDEX sessao_ordem_por_ordem ON sessao_ordem_retirada(organizacao_id,ordem_id,sessao_id);
CREATE VIEW ordem_retirada_consulta WITH(security_invoker=true) AS SELECT o.*,e.estado,e.versao,EXISTS(SELECT 1 FROM item_ordem_retirada i WHERE i.organizacao_id=o.organizacao_id AND i.ordem_id=o.id AND i.sensivel) sensivel FROM ordem_retirada o JOIN LATERAL(SELECT estado,versao FROM evento_ordem_retirada WHERE organizacao_id=o.organizacao_id AND ordem_id=o.id ORDER BY versao DESC LIMIT 1) e ON true;
CREATE VIEW sessao_acesso_consulta WITH(security_invoker=true) AS SELECT s.*,e.tipo estado,e.versao,CASE WHEN e.tipo='ACCESS_CLOSED' THEN e.ocorrida_em END encerrada_em, s.expira_em<=clock_timestamp() expirada FROM sessao_acesso s JOIN LATERAL(SELECT tipo,versao,ocorrida_em FROM evento_acesso WHERE organizacao_id=s.organizacao_id AND sessao_id=s.id ORDER BY versao DESC LIMIT 1) e ON true;
